package com.chahinaz.pos.reporting;
import static com.chahinaz.pos.reporting.ReportingDtos.*;import java.io.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Service;
@Service public class ExcelExportService {
 public byte[] workbook(String title,ReportRange range,List<String> headers,List<? extends List<?>> rows){try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet sh=wb.createSheet("Report");CellStyle titleStyle=wb.createCellStyle();Font tf=wb.createFont();tf.setBold(true);tf.setFontHeightInPoints((short)16);titleStyle.setFont(tf);CellStyle head=wb.createCellStyle();Font hf=wb.createFont();hf.setBold(true);head.setFont(hf);head.setFillForegroundColor(IndexedColors.LIGHT_ORANGE.getIndex());head.setFillPattern(FillPatternType.SOLID_FOREGROUND);CellStyle money=wb.createCellStyle();money.setDataFormat(wb.createDataFormat().getFormat("$#,##0.00;[Red]-$#,##0.00"));Row t=sh.createRow(0);t.createCell(0).setCellValue(safe(title));t.getCell(0).setCellStyle(titleStyle);sh.createRow(1).createCell(0).setCellValue("Generated: "+Instant.now());sh.createRow(2).createCell(0).setCellValue("Range: "+range.from()+" to "+range.to()+" ("+range.zone().getId()+")");Row h=sh.createRow(4);for(int i=0;i<headers.size();i++){Cell c=h.createCell(i);c.setCellValue(headers.get(i));c.setCellStyle(head);}int n=5;for(List<?> values:rows){Row row=sh.createRow(n++);for(int i=0;i<values.size();i++){Object v=values.get(i);Cell c=row.createCell(i);if(v instanceof BigDecimal b){c.setCellValue(b.doubleValue());c.setCellStyle(money);}else if(v instanceof Number x)c.setCellValue(x.doubleValue());else if(v instanceof Boolean b)c.setCellValue(b);else c.setCellValue(safe(v==null?"":v.toString()));}}for(int i=0;i<headers.size();i++){sh.autoSizeColumn(i);sh.setColumnWidth(i,Math.min(sh.getColumnWidth(i)+512,12000));}sh.createFreezePane(0,5);wb.write(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException("Could not create workbook",e);}}
 static String safe(String value){if(!value.isEmpty()&&"=+-@".indexOf(value.charAt(0))>=0)return "'"+value;return value;}
 public byte[] export(String type,ReportRange r,ReportingService reports){return switch(type){case"sales"->{List<SalesPeriod>x=reports.sales(r,"daily");yield workbook("Sales report",r,List.of("Period","Transactions","Units","Gross USD","Discounts USD","Refunds USD","Net USD","Average USD","Gross profit USD"),x.stream().map(v->List.of(v.period(),v.salesCount(),v.unitsSold(),v.grossSales(),v.discounts(),v.refunds(),v.netSales(),v.averageTransactionValue(),v.grossProfit())).toList());}case"products"->{List<ProductPerformance>x=reports.products(r,"revenue");yield workbook("Product performance",r,List.of("SKU","Product","Units sold","Gross USD","Discounts USD","Net USD","Returned qty","Refund USD","COGS USD","Gross profit USD","Stock"),x.stream().map(v->List.of(v.sku(),v.productName(),v.unitsSold(),v.grossRevenue(),v.discounts(),v.netRevenue(),v.quantityReturned(),v.refundAmount(),v.costOfGoodsSold(),v.grossProfit(),v.currentStock())).toList());}case"inventory"->{List<InventoryRow>x=reports.inventory(r,null,null,null);yield workbook("Inventory",r,List.of("SKU","Product","Category","Stock","Threshold","Status","Unit cost USD","Value USD","Units sold","Restocked returns","Non-restockable returns"),x.stream().map(v->List.of(v.sku(),v.productName(),v.category(),v.stock(),v.lowStockThreshold(),v.stockStatus(),v.currentUnitCost(),v.inventoryValue(),v.unitsSold(),v.unitsRestocked(),v.nonRestockableReturns())).toList());}case"registers"->{List<RegisterReport>x=reports.registers(r);yield workbook("Register sessions",r,List.of("Employee","Opened","Closed","Status","Opening USD","Opening LBP","Expected USD","Expected LBP","Actual USD","Actual LBP","Difference USD","Difference LBP","Transactions","Cash sales USD","Cash sales LBP","Refunds USD","Refunds LBP"),x.stream().map(v->Arrays.asList(v.employeeName(),v.openedAt(),v.closedAt(),v.status(),v.openingUsd(),v.openingLbp(),v.expectedUsd(),v.expectedLbp(),v.actualUsd(),v.actualLbp(),v.differenceUsd(),v.differenceLbp(),v.transactionCount(),v.cashSalesUsd(),v.cashSalesLbp(),v.refundsUsd(),v.refundsLbp())).toList());}case"returns"->{List<ReturnReport>x=reports.returns(r);yield workbook("Returns and refunds",r,List.of("Sale","SKU","Product","Quantity","Amount USD","Restockable","Employee","Reason","Time"),x.stream().map(v->List.of(v.saleNumber(),v.sku(),v.productName(),v.quantity(),v.amountUsd(),v.restockable(),v.employee(),v.reason(),v.occurredAt())).toList());}case"discounts"->{List<DiscountReport>x=reports.discounts(r);yield workbook("Discounts",r,List.of("Sale","SKU","Product","Amount USD","Percentage","Employee","Time"),x.stream().map(v->Arrays.asList(v.saleNumber(),v.sku(),v.productName(),v.amount(),v.percentage(),v.employee(),v.occurredAt())).toList());}case"overrides"->{List<OverrideReport>x=reports.overrides(r);yield workbook("Price overrides",r,List.of("Sale","SKU","Product","Original USD","Effective USD","Difference USD","Requested by","Approved by","Reason","Time"),x.stream().map(v->Arrays.asList(v.saleNumber(),v.sku(),v.productName(),v.originalPrice(),v.effectivePrice(),v.difference(),v.requestingEmployee(),v.approvingEmployee(),v.reason(),v.occurredAt())).toList());}default->throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Unknown export type");};}
}

